CREATE DEFINER=`root`@`localhost` PROCEDURE `generate_orders_and_details` ()  BEGIN
    DECLARE done INT DEFAULT 0;
    DECLARE cust_id INT;
    DECLARE emp_id INT;
    DECLARE shipper_id INT;
    DECLARE status_id INT;
    DECLARE order_id INT;
    DECLARE num_orders INT;
    DECLARE i INT;

   
    DECLARE cust_cursor CURSOR FOR SELECT id FROM customers;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

    OPEN cust_cursor;

    read_loop: LOOP
        FETCH cust_cursor INTO cust_id;
        IF done THEN
            LEAVE read_loop;
        END IF;

 
        SET num_orders = FLOOR(100 + (RAND() * 401)); -- 100 a 500

        SET i = 1;
        WHILE i <= num_orders DO
            
            SELECT id INTO emp_id FROM employees ORDER BY RAND() LIMIT 1;
            SELECT id INTO shipper_id FROM shippers ORDER BY RAND() LIMIT 1;
            SELECT id INTO status_id FROM orders_status ORDER BY RAND() LIMIT 1;

            
                employee_id,
                customer_id,
                order_date,
                shipped_date,
                shipper_id,
                ship_name,
                ship_address,
                ship_city,
                ship_state_province,
                ship_zip_postal_code,
                ship_country_region,
                shipping_fee,
                taxes,
                payment_type,
                paid_date,
                notes,
                status_id
            ) VALUES (
                emp_id,
                cust_id,
                DATE_SUB(CURDATE(), INTERVAL FLOOR(RAND() * 1000) DAY),
                DATE_SUB(CURDATE(), INTERVAL FLOOR(RAND() * 1000) DAY),
                shipper_id,
                CONCAT('Order for cust ', cust_id),
                '123 Test Street',
                'CityX',
                'StateY',
                LPAD(FLOOR(RAND() * 99999), 5, '0'),
                'CountryZ',
                ROUND(RAND() * 200, 2),
                ROUND(RAND() * 50, 2),
                'Credit Card',
                DATE_SUB(CURDATE(), INTERVAL FLOOR(RAND() * 1000) DAY),
                'Generated order',
                status_id
            );

           
            SET order_id = LAST_INSERT_ID();

            
            SET @num_details = FLOOR(1 + (RAND() * 10));
            SET @j = 1;
            WHILE @j <= @num_details DO
                SET @prod_id = (SELECT id FROM products ORDER BY RAND() LIMIT 1);
                SET @unit_price = (SELECT standard_cost + (RAND() * 50) FROM products WHERE id = @prod_id LIMIT 1);
                SET @quantity = FLOOR(1 + (RAND() * 10));

                    order_id,
                    product_id,
                    quantity,
                    unit_price,
                    discount,
                    status_id,
                    date_allocated
                ) VALUES (
                    order_id,
                    @prod_id,
                    @quantity,
                    @unit_price,
                    ROUND(RAND() * 0.2, 2), 
                    status_id,
                    DATE_SUB(CURDATE(), INTERVAL FLOOR(RAND() * 1000) DAY)
                );

                SET @j = @j + 1;
            END WHILE;

            SET i = i + 1;
        END WHILE;

    END LOOP;

    CLOSE cust_cursor;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `generate_purchase_orders` (IN `p_count` INT)  BEGIN
  DECLARE i INT DEFAULT 0;
  DECLARE v_supplier INT;
  DECLARE v_created_by INT;
  DECLARE v_status INT;
  DECLARE v_creation DATETIME;
  DECLARE v_submitted DATETIME;
  DECLARE v_expected DATETIME;
  DECLARE v_payment_date DATETIME;
  DECLARE v_shipping DECIMAL(19,4);
  DECLARE v_taxes DECIMAL(19,4);
  DECLARE v_payment_amount DECIMAL(19,4);
  DECLARE v_payment_method VARCHAR(50);
  DECLARE v_notes TEXT;
  DECLARE v_approved_by INT;
  DECLARE v_submitted_by INT;

  -- protección: si no hay suppliers o employees o statuses -> abortamos
  IF (SELECT COUNT(*) FROM suppliers) = 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No suppliers found. Aborting.';
  END IF;
  IF (SELECT COUNT(*) FROM employee) = 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No employees found. Aborting.';
  END IF;
  IF (SELECT COUNT(*) FROM purchase_order_status) = 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No purchase_order_status found. Aborting.';
  END IF;

  WHILE i < p_count DO
    -- elegir IDs válidos al azar (siempre existentes)
    SELECT id INTO v_supplier FROM suppliers ORDER BY RAND() LIMIT 1;
    SELECT employeeid INTO v_created_by FROM employee ORDER BY RAND() LIMIT 1;
    SELECT id INTO v_status FROM purchase_order_status ORDER BY RAND() LIMIT 1;

    -- fechas: creación aleatoria en los últimos 3 años
    SET v_creation = DATE_SUB(NOW(), INTERVAL FLOOR(RAND()*365*3) DAY);
    -- envío/esperado aleatorio después de creación
    SET v_expected = DATE_ADD(v_creation, INTERVAL FLOOR(RAND()*60) DAY);

    -- submitted: null si NEW (puede ajustarse según tus códigos de estado)
    IF v_status = 0 THEN
      SET v_submitted = NULL;
    ELSE
      SET v_submitted = DATE_ADD(v_creation, INTERVAL FLOOR(RAND()*5) DAY);
    END IF;

    SET v_shipping = ROUND(RAND()*150,4);
    SET v_taxes   = ROUND(RAND()*200,4);
    SET v_payment_amount = 0.00;
    SET v_payment_date = NULL;
    SET v_payment_method = NULL;
    SET v_approved_by = NULL;
    SET v_submitted_by = v_created_by;

    -- si el estado es Aprobado(2) o Cerrado(3) (ajusta si tus ids difieren),
    -- generamos pago / approved_by / método
    IF v_status IN (2,3) THEN
      SET v_payment_amount = ROUND(10 + RAND()*20000, 4); -- entre 10 y 20010
      SET v_payment_date = DATE_ADD(v_creation, INTERVAL FLOOR(RAND()*30) DAY);
      SELECT employeeid INTO v_approved_by FROM employee ORDER BY RAND() LIMIT 1;
      SET v_payment_method = ELT(FLOOR(RAND()*4)+1, 'Wire Transfer','Credit Card','Cash','Check');
    END IF;

    SET v_notes = CONCAT('Auto-generated order - ', DATE_FORMAT(NOW(), '%Y%m%d%H%i%s'), ' - loop=', i);

      supplier_id,
      created_by,
      submitted_date,
      creation_date,
      status_id,
      expected_date,
      shipping_fee,
      taxes,
      payment_date,
      payment_amount,
      payment_method,
      notes,
      approved_by,
      approved_date,
      submitted_by
    ) VALUES (
      v_supplier,
      v_created_by,
      v_submitted,
      v_creation,
      v_status,
      v_expected,
      v_shipping,
      v_taxes,
      v_payment_date,
      v_payment_amount,
      v_payment_method,
      v_notes,
      v_approved_by,
      v_payment_date,
      v_submitted_by
    );

    SET i = i + 1;
  END WHILE;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `seed_purchase_orders` ()  BEGIN
  DECLARE sup_id INT;
  DECLARE finished INT DEFAULT 0;
  DECLARE order_count INT;
  DECLARE i INT;

  
  DECLARE cur CURSOR FOR SELECT id FROM suppliers;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET finished = 1;

  OPEN cur;
  read_loop: LOOP
    FETCH cur INTO sup_id;
    IF finished = 1 THEN 
      LEAVE read_loop;
    END IF;

    SET order_count = FLOOR(50 + (RAND() * 150));
    SET i = 0;

    WHILE i < order_count DO
      VALUES (
        sup_id,
        FLOOR(1 + (RAND() * 10)), 
        DATE_SUB(NOW(), INTERVAL FLOOR(RAND() * 365) DAY), 
        DATE_ADD(NOW(), INTERVAL FLOOR(RAND() * 60) DAY),
        FLOOR(1 + (RAND() * 4)), 
        ROUND(RAND() * 10000, 2), 
        DATE_SUB(NOW(), INTERVAL FLOOR(RAND() * 180) DAY),
        ELT(FLOOR(1 + RAND() * 3), 'Transferencia', 'Cheque', 'Efectivo'),
        'Orden generada automáticamente'
      );
      SET i = i + 1;
    END WHILE;
  END LOOP;

  CLOSE cur;
END$$

